"""Weekly insight quality — generated by the live LLM for synthetic users, checked automatically.

Synthetic histories (lumina/memory/synthetic.py; invented, not user data): each user has three
sessions this week and twelve earlier ones; for half of them, an earlier paraphrase of this week's
newest story is planted ~1 year back.  lumina.insights.weekly runs end-to-end (pattern miner →
LLM → output guard + Llama Guard).  Measured:
  produced          insights that passed the guards (else status "unavailable")
  names_the_past    when an earlier moment was found: the text names when it was (its month or "a year ago")
  invents_the_past  when none was found: the text still names a month (a made-up link)
  grounded          the text is closer (MiniLM cosine) to this user's week than to another user's week
  ends_with_question, length_ok (4–6 sentences, as the prompt asks)
Output: eval/reports/insight_quality.json
"""

from __future__ import annotations

import json
import random
import re
import tempfile
from datetime import timedelta
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[2]
N_USERS = 12
_MONTHS = re.compile(r"\b(January|February|March|April|May|June|July|August|September|October|November|December)\b")


def _build(store, rng, embed, now, planted: bool):
    from lumina.auth.passwords import hash_password
    from lumina.memory.synthetic import SCENARIOS
    keys = [k for k in SCENARIOS if k != "good_week"]
    user = store.create_user(f"u{rng.random()}@eval.local", hash_password("x" * 12), "", consent=True,
                             now=now - timedelta(days=500))
    this_week = rng.sample(keys, 3)
    plan = [(5 - 2 * i, k, rng.randrange(3)) for i, k in enumerate(this_week)]        # newest = this_week[2]
    others = [k for k in keys if k not in this_week]
    plan += [(rng.randint(30, 300), rng.choice(others), rng.randrange(3)) for _ in range(12)]
    if planted:
        variant = next(v for v in range(3) if v != plan[2][2])
        plan.append((rng.randint(340, 390), this_week[2], variant))
    for days, key, variant in plan:
        sc, when = SCENARIOS[key], now - timedelta(days=days)
        s = store.create_session(user["id"], "open", now=when)
        for i in range(3):
            tid = store.add_turn(s["id"], user["id"], intent="venting", emotion=sc["emotion"], sentiment="negative",
                                 pain_points=sc["pain"], macro=sc["macro"], risk_level="none",
                                 now=when + timedelta(minutes=i))
            store.set_turn_elements(tid, sc["elements"])
        summary = sc["summaries"][variant]
        store.save_episode(s["id"], user["id"], summary=summary, themes=[p.split(" and ")[0] for p in sc["pain"]],
                           elements={}, emotions=[sc["emotion"]], had_crisis=False, embedding=embed(summary),
                           now=when + timedelta(minutes=10))
    return user, [SCENARIOS[k]["summaries"][v] for _, k, v in plan[:3]]


def main() -> dict:
    from lumina.config import LLM_MODEL, LLM_PROVIDER
    from lumina.insights.weekly import weekly_insight
    from lumina.memory.embeddings import embed
    from lumina.memory.store import Store, utcnow

    rng, now = random.Random(29), utcnow()
    rows = []
    with tempfile.TemporaryDirectory() as tmp:
        store = Store(Path(tmp) / "eval.db")
        users = [_build(store, rng, embed, now, planted=i % 2 == 0) for i in range(N_USERS)]
        for idx, (user, week) in enumerate(users):
            out = weekly_insight(store, user, now=now)
            row = {"status": out["status"]}
            if out["status"] == "ready":
                text, ev = out["insight"]["text"], out["insight"]["evidence"]
                echo = ev.get("echo")
                v = embed(text)
                own = float(v @ np.mean([embed(s) for s in week], axis=0))
                other_week = users[(idx + 1) % len(users)][1]
                other = float(v @ np.mean([embed(s) for s in other_week], axis=0))
                sentences = [s for s in re.split(r"(?<=[.!?])\s+", text.strip()) if s]
                # Months of this week's own dates may be named; any other month is a link to the past.
                this_week = {(now - timedelta(days=d)).strftime("%B") for d in range(8)}
                past_months = set(_MONTHS.findall(text)) - this_week
                row.update({
                    "echo_found": bool(echo), "text": text,
                    "names_the_past": bool(echo) and (echo["then"].split()[0] in text or "year ago" in text
                                                      or "last year" in text),
                    "invents_the_past": not echo and bool(past_months),
                    "grounded": own > other, "ends_with_question": text.rstrip().endswith("?"),
                    "length_ok": 4 <= len(sentences) <= 6, "chars": len(text)})
            rows.append(row)

    ready = [r for r in rows if r["status"] == "ready"]
    with_echo = [r for r in ready if r["echo_found"]]
    without = [r for r in ready if not r["echo_found"]]

    def rate(rs, key):
        return round(sum(r[key] for r in rs) / len(rs), 3) if rs else None
    out = {"n_users": len(rows), "llm": f"{LLM_PROVIDER}:{LLM_MODEL}",
           "produced": round(len(ready) / len(rows), 3), "echo_found": len(with_echo),
           "names_the_past": rate(with_echo, "names_the_past"), "invents_the_past": rate(without, "invents_the_past"),
           "grounded": rate(ready, "grounded"), "ends_with_question": rate(ready, "ends_with_question"),
           "length_ok": rate(ready, "length_ok"), "rows": rows}
    rep = ROOT / "eval" / "reports"
    rep.mkdir(parents=True, exist_ok=True)
    (rep / "insight_quality.json").write_text(json.dumps(out, indent=2), encoding="utf-8")
    print(json.dumps({k: v for k, v in out.items() if k != "rows"}, indent=2))
    return out


if __name__ == "__main__":
    main()
